 {view.src&&!VIEWS.some(v=>v.id===view.id)&&<div className="last-capture"><img crossOrigin="anonymous" src={view.src} alt="Latest product reference"/><span>{view.id===VIEWS[0].id?'Example product reference':'Latest product reference'}<small>{view.title}</small></span></div>}
