 <div className="results-grid">{(results.length?results:EXAMPLES).map((r,i)=><article className="result-card" key={r.id}>{r.status==='ready'?<button className="result-image" onClick={()=>{if(r.lineup){location.href='/lineup?visual='+r.id;return}setSelected(r);setUpscaleOpen(false);setAreaOpen(false);setCompare(false);if(refinementOwner.current!==r.id){setRefinement('');setRefinementImages([]);refinementOwner.current=r.id}setReferenceMode(r.referenceMode||'creative');setProvider(r.provider||'openai');setImageModel(r.provider==='google'?(r.model||GEMINI_IMAGE_MODELS[0].id):r.provider==='higgsfield'?(r.model||HIGGSFIELD_IMAGE_MODEL):HIGGSFIELD_IMAGE_MODELS[0].id);setSize(r.upscale?'2048x1152':r.size||'2048x1152')}}><img crossOrigin="anonymous" src={r.src} alt={r.title}/><span><Maximize2 size={17}/></span>{r.width&&<small>{r.width} × {r.height}</small>}</button>:<div className={'generation-placeholder '+r.status}>{r.provider==='higgsfield'?<><Sparkles size={24}/><b>{['draft','quoted'].includes(r.jobStatus||'')?'Not started':['unknown','submitting'].includes(r.jobStatus||'')?'Check original request':r.status==='failed'?'Generation could not finish':'Creating with Higgsfield'}</b><p>{r.error||(['draft','quoted'].includes(r.jobStatus||'')?'This draft has not generated an image.':'Your request is saved. Return within seven days to archive the finished image.')}</p>{['draft','quoted'].includes(r.jobStatus||'')&&<button className="secondary" disabled={busy} onClick={()=>void imageAction(r,'generate')}>Generate image</button>}{['unknown','submitting'].includes(r.jobStatus||'')&&<button className="secondary" disabled={busy} onClick={()=>void imageAction(r,'recover')}>Recover original request</button>}{['queued','in_progress','archiving'].includes(r.jobStatus||'')&&<button className="secondary" disabled={busy} onClick={()=>void imageAction(r,'refresh')}>Refresh image</button>}</>:r.status==='pending'?<><LoaderCircle size={28} className="spin"/><b>Creating your visual</b><p>Lighting, materials and atmosphere.<br/>Keep this page open while it renders.</p></>:<><Info size={24}/><b>Generation could not finish</b><p>{r.error||'Try again after checking your connection.'}</p></>}</div>}<h3><span>{String(i+1).padStart(2,'0')}</span>{r.title}</h3>{r.upscale&&<p className="visual-generator-label">{r.upscale.method==='topaz-api'?'API upscale':'Imported upscale'} · {upscaleModel(r.upscale.modelId).label}</p>}{r.provider&&<p className="visual-generator-label">{r.provider==='higgsfield'?'Higgsfield · '+higgsImageModel(r.model).label:r.provider==='google'?'Google · '+geminiImageModel(r.model).label:'ChatGPT / OpenAI'}</p>}<div className="generation-card-actions">{r.status==='ready'&&<button className="secondary" disabled={busy||preparing||!!managingVisual} onClick={()=>applyAsInspiration(r)}>Use as inspiration</button>}{!r.example&&r.status!=='pending'&&<button className="secondary" disabled={busy||preparing||!!managingVisual} onClick={()=>void removeVisual(r)} aria-label={'Delete '+r.title}>{managingVisual===r.id?'Deleting…':'Delete'}</button>}</div></article>)}</div>
